class Solution {
    private $parent = [];
    private $rank = [];

    // Union-Find find with path compression
    private function find(int $x): int {
        if ($this->parent[$x] !== $x) {
            $this->parent[$x] = $this->find($this->parent[$x]);
        }
        return $this->parent[$x];
    }

    // Union-Find union by rank
    private function union(int $x, int $y): void {
        $rootX = $this->find($x);
        $rootY = $this->find($y);
        if ($rootX !== $rootY) {
            if ($this->rank[$rootX] < $this->rank[$rootY]) {
                $this->parent[$rootX] = $rootY;
            } else if ($this->rank[$rootX] > $this->rank[$rootY]) {
                $this->parent[$rootY] = $rootX;
            } else {
                $this->parent[$rootY] = $rootX;
                $this->rank[$rootX]++;
            }
        }
    }

    // Get all prime factors of a number
    private function primeFactors(int $num): array {
        $factors = [];

        // Check for 2 as factor
        while ($num % 2 === 0) {
            $factors[2] = true;
            $num = intdiv($num, 2);
        }

        // Check odd factors
        $f = 3;
        $limit = (int) sqrt($num);
        while ($f <= $limit && $num > 1) {
            while ($num % $f === 0) {
                $factors[$f] = true;
                $num = intdiv($num, $f);
                $limit = (int) sqrt($num);
            }
            $f += 2;
        }

        // If num > 1, it's prime
        if ($num > 1) {
            $factors[$num] = true;
        }

        return array_keys($factors);
    }

    function gcdSort(array $nums): bool {
        $n = count($nums);
        $maxVal = max($nums);

        // Initialize union find for numbers up to maxVal
        // We will union by factors, so parents array size maxVal+1
        // Only numbers and prime factors up to maxVal are used
        $this->parent = [];
        $this->rank = [];

        for ($i = 0; $i <= $maxVal; $i++) {
            $this->parent[$i] = $i;
            $this->rank[$i] = 0;
        }

        // Union every number with its prime factors
        foreach ($nums as $num) {
            $factors = $this->primeFactors($num);
            foreach ($factors as $factor) {
                $this->union($num, $factor);
            }
        }

        $sorted = $nums;
        sort($sorted);

        // For each index, check if nums[i] and sorted[i] share same root
        // which means they are connected by some gcd>1 swaps
        for ($i = 0; $i < $n; $i++) {
            if ($this->find($nums[$i]) !== $this->find($sorted[$i])) {
                return false;
            }
        }

        return true;
    }
}

